<script setup>
import {useForm,Head,Link} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';import Errors from '../../Components/Errors.vue';import {useI18n} from '../../lib/i18n.js';
const props=defineProps({collection:Object,joinUuid:String,existingMember:Boolean});const {t}=useI18n(),form=useForm({progress_consent:false});
function accept(){if(form.processing)return;form.post(props.existingMember?`/collections/${props.collection.id}/consent`:`/s/${props.joinUuid}/join`);}
function cancelJoin(){if(!form.processing)form.post(`/s/${props.joinUuid}/join/cancel`);}
function leave(){form.delete(`/collections/${props.collection.id}/membership`);}
</script><template><Head :title="t('Choose what you share')"/><AppLayout :title="t('Choose what you share')" :subtitle="collection.title" :shared="!existingMember"><section class="panel"><h2>{{t('Share progress with this collection’s owner')}}</h2><p>{{t('The owner can see your name and your existing and future learning results for this collection, including completed sessions and success summaries.')}}</p><p>{{t('You can return to Progress sharing choices to withdraw consent and leave. The owner will no longer see your progress.')}}</p><p>{{t('Your personal notes are never included. This choice applies only to this collection.')}}</p><p>{{t(existingMember?'Declining leaves this collection. Your personal history and notes are retained, but you lose member access.':'Declining does not join the collection and does not share your progress.')}}</p><form @submit.prevent="accept"><Errors :errors="form.errors"/><label class="consent-check"><input v-model="form.progress_consent" type="checkbox" required/>{{t('I agree to share my existing and future progress with this collection’s owner.')}}</label><div class="form-actions"><button v-if="existingMember" type="button" class="button secondary" :disabled="form.processing" @click="leave">{{t('Decline and leave collection')}}</button><button v-else type="button" class="button secondary" :disabled="form.processing" @click="cancelJoin">{{t('Decline and go back')}}</button><button class="button" :disabled="!form.progress_consent||form.processing">{{t(existingMember?'Agree and keep membership':'Agree and join')}}</button></div></form></section></AppLayout></template><style scoped>.consent-check{display:flex;align-items:flex-start;gap:12px;margin-top:24px}.consent-check input{width:auto;flex-shrink:0;margin-top:4px}.panel p{line-height:1.6}@media(max-width:600px){.form-actions{flex-direction:column;align-items:stretch}}</style>